INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('e2e42209-32ff-41eb-a96b-73de5b0fb362', NULL, 'system', 'notifications.update', 'notifications', '88b80507-5af8-488c-bb25-d503987048ac', '{"template":"Your order {{order_number}} is being returned to us. Questions? Call {{store_phone}}. - {{store_name}}"}', '{"template":"Hi {{customer_first_name}}, the parcel for order {{order_number}} is on its way back to us. Questions? Call us at {{store_phone}} or reply here.\n\nThe {{store_name}} team"}', '{}', '2026-10-23T07:15:18.401Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('2daae8cf-5f71-420b-877b-7589ac2b8008', NULL, 'system', 'notifications.update', 'notifications', 'e5202cdc-b037-45a9-8998-c16fa9ffe57b', '{"template":"Your payment of {{payment_amount}} for order {{order_number}} did not go through. Try again: {{track_order_url}} - {{store_name}}"}', '{"template":"Hi {{customer_first_name}}, your payment of {{payment_amount}} for order {{order_number}} did not go through. You can try again here: {{track_order_url}} at any time.\n\nThe {{store_name}} team"}', '{}', '2026-10-23T07:15:18.401Z', '00000000-0000-4000-8000-000000000001');
INSERT INTO "audit_logs" ("id", "actor_id", "actor_email", "action", "entity_type", "entity_id", "old_values", "new_values", "metadata", "created_at", "merchant_id") VALUES ('854116b9-311d-4dad-8445-01d6b0dd6aff', NULL, 'system', 'notifications.update', 'notifications', 'ec66fc91-cec9-4c28-bef3-83a598f3cf77', '{"template":"We received {{payment_amount}} for order {{order_number}}. Thank you! - {{store_name}}"}', '{"template":"Hi {{customer_first_name}}, we received your payment of {{payment_amount}} for order {{order_number}}. Thank you!\n\nThe {{store_name}} team"}', '{}', '2026-10-23T07:15:18.401Z', '00000000-0000-4000-8000-000000000001');
