INSERT INTO "notification_defaults" ("channel", "event", "subject", "template") VALUES ('EMAIL', 'RETURN_INITIATED', 'Order {{ order.name }} is being returned', replace('{% assign accent = shop.accent_color | default: "#111827" %}<!doctype html>⏎<html lang="en">⏎<head>⏎<meta charset="utf-8">⏎<meta name="viewport" content="width=device-width, initial-scale=1">⏎<title>Your order is being returned</title>⏎</head>⏎<body style="margin:0;padding:0;background:#f4f5f7;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f4f5f7;">⏎<tr><td align="center" style="padding:32px 12px;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;">⏎<tr><td style="padding:28px 32px 0;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>⏎<td>{% if shop.logo_url %}<img src="{{ shop.logo_url }}" alt="{{ shop.name }}" height="36" style="display:block;height:36px;max-width:180px;border:0;">{% else %}<span style="font-size:20px;font-weight:700;color:#111827;">{{ shop.name }}</span>{% endif %}</td>⏎<td align="right" style="font-size:13px;color:#6b7280;">Order {{ order.name }}</td>⏎</tr></table>⏎</td></tr>⏎<tr><td style="padding:24px 32px 4px;">⏎<h1 style="margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;">Your order is being returned</h1>⏎<p style="margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;">Hi {{ customer.first_name | default: "there" }}, the parcel for order {{ order.name }} is on its way back to us.</p>⏎<p style="margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;">Questions? Reply to this email{% if shop.phone %} or call us at {{ shop.phone }}{% endif %}.</p>⏎</td></tr>⏎⏎⏎<tr><td style="padding:28px 32px 28px;">⏎<p style="margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>⏎</td></tr>⏎</table>⏎</td></tr>⏎</table>⏎</body>⏎</html>', '⏎', char(10)));
INSERT INTO "notification_defaults" ("channel", "event", "subject", "template") VALUES ('EMAIL', 'ORDER_RETURNED', 'Return received for order {{ order.name }}', replace('{% assign accent = shop.accent_color | default: "#111827" %}<!doctype html>⏎<html lang="en">⏎<head>⏎<meta charset="utf-8">⏎<meta name="viewport" content="width=device-width, initial-scale=1">⏎<title>We received your return</title>⏎</head>⏎<body style="margin:0;padding:0;background:#f4f5f7;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f4f5f7;">⏎<tr><td align="center" style="padding:32px 12px;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background:#ffffff;border-radius:12px;font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;color:#111827;">⏎<tr><td style="padding:28px 32px 0;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>⏎<td>{% if shop.logo_url %}<img src="{{ shop.logo_url }}" alt="{{ shop.name }}" height="36" style="display:block;height:36px;max-width:180px;border:0;">{% else %}<span style="font-size:20px;font-weight:700;color:#111827;">{{ shop.name }}</span>{% endif %}</td>⏎<td align="right" style="font-size:13px;color:#6b7280;">Order {{ order.name }}</td>⏎</tr></table>⏎</td></tr>⏎<tr><td style="padding:24px 32px 4px;">⏎<h1 style="margin:0 0 12px;font-size:22px;line-height:1.3;color:#111827;">We received your return</h1>⏎<p style="margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;">Hi {{ customer.first_name | default: "there" }}, the returned parcel for order {{ order.name }} has reached us.</p>⏎{% if order.paid_amount > 0 %}<p style="margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;">We will contact you about your payment of {{ order.paid_amount | money }}.</p>{% endif %}⏎</td></tr>⏎⏎⏎<tr><td style="padding:28px 32px 28px;">⏎<p style="margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>⏎</td></tr>⏎</table>⏎</td></tr>⏎</table>⏎</body>⏎</html>', '⏎', char(10)));
INSERT INTO "notification_defaults" ("channel", "event", "subject", "template") VALUES ('WHATSAPP', 'ORDER_CREATED', NULL, replace('Hi {{customer_first_name}}, thank you for your order {{order_number}} of {{total}}. We will call you shortly to confirm it.⏎⏎Thank you for shopping with {{store_name}} today.', '⏎', char(10)));
INSERT INTO "notification_defaults" ("channel", "event", "subject", "template") VALUES ('WHATSAPP', 'ORDER_CONFIRMED', NULL, replace('Hi {{customer_first_name}}, your order {{order_number}} is confirmed and we are getting it ready. Amount to pay on delivery: {{cod_amount}}.⏎⏎Thank you, the {{store_name}} team', '⏎', char(10)));
INSERT INTO "notification_defaults" ("channel", "event", "subject", "template") VALUES ('WHATSAPP', 'PRE_ORDER_CONFIRMED', NULL, replace('Hi {{customer_first_name}}, your pre-order {{order_number}} is confirmed. We will ship it as soon as it arrives in stock.⏎⏎Thank you, the {{store_name}} team', '⏎', char(10)));
INSERT INTO "notification_defaults" ("channel", "event", "subject", "template") VALUES ('WHATSAPP', 'ADVANCE_REQUIRED', NULL, replace('Hi {{customer_first_name}}, to confirm order {{order_number}} please pay an advance of {{advance_amount}} here: {{track_order_url}} and we will ship it right away.⏎⏎Thank you, the {{store_name}} team', '⏎', char(10)));
INSERT INTO "notification_defaults" ("channel", "event", "subject", "template") VALUES ('WHATSAPP', 'PAYMENT_RECEIVED', NULL, replace('Hi {{customer_first_name}}, we received your payment of {{payment_amount}} for order {{order_number}}. Thank you!⏎⏎The {{store_name}} team', '⏎', char(10)));
INSERT INTO "notification_defaults" ("channel", "event", "subject", "template") VALUES ('WHATSAPP', 'PAYMENT_FAILED', NULL, replace('Hi {{customer_first_name}}, your payment of {{payment_amount}} for order {{order_number}} did not go through. You can try again here: {{track_order_url}} at any time.⏎⏎The {{store_name}} team', '⏎', char(10)));
INSERT INTO "notification_defaults" ("channel", "event", "subject", "template") VALUES ('WHATSAPP', 'ORDER_SHIPPED', NULL, replace('Hi {{customer_first_name}}, your order {{order_number}} has been handed to {{courier_name}}. Tracking number: {{tracking_number}}. Track it here: {{tracking_url}} anytime.⏎⏎The {{store_name}} team', '⏎', char(10)));
INSERT INTO "notification_defaults" ("channel", "event", "subject", "template") VALUES ('WHATSAPP', 'OUT_FOR_DELIVERY', NULL, replace('Hi {{customer_first_name}}, your order {{order_number}} is out for delivery today. Please keep {{cod_amount}} ready for the delivery person.⏎⏎The {{store_name}} team', '⏎', char(10)));
INSERT INTO "notification_defaults" ("channel", "event", "subject", "template") VALUES ('WHATSAPP', 'ORDER_DELIVERED', NULL, replace('Hi {{customer_first_name}}, your order {{order_number}} was delivered. We hope you love it! Reply here if anything is not right.⏎⏎The {{store_name}} team', '⏎', char(10)));
INSERT INTO "notification_defaults" ("channel", "event", "subject", "template") VALUES ('WHATSAPP', 'ORDER_CANCELLED', NULL, replace('Hi {{customer_first_name}}, your order {{order_number}} has been cancelled. Questions? Call us at {{store_phone}} or reply here.⏎⏎The {{store_name}} team', '⏎', char(10)));
INSERT INTO "notification_defaults" ("channel", "event", "subject", "template") VALUES ('WHATSAPP', 'RETURN_INITIATED', NULL, replace('Hi {{customer_first_name}}, the parcel for order {{order_number}} is on its way back to us. Questions? Call us at {{store_phone}} or reply here.⏎⏎The {{store_name}} team', '⏎', char(10)));
INSERT INTO "notification_defaults" ("channel", "event", "subject", "template") VALUES ('WHATSAPP', 'ORDER_RETURNED', NULL, replace('Hi {{customer_first_name}}, the returned parcel for order {{order_number}} has reached us. We will be in touch soon.⏎⏎The {{store_name}} team', '⏎', char(10)));
