:1.6;color:#374151;">We will contact you about your payment of {{ order.paid_amount | money }}.</p>{% endif %}⏎</td></tr>⏎⏎⏎<tr><td style="padding:28px 32px 28px;">⏎<p style="margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>⏎</td></tr>⏎</table>⏎</td></tr>⏎</table>⏎</body>⏎</html>', '⏎', char(10)), '2026-10-23T07:15:16.032Z', '2026-10-23T07:15:18.401Z', 'Returned', '[]', '00000000-0000-4000-8000-000000000001', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL);
