INSERT INTO "platform_automation_rules" ("id", "name", "description", "trigger", "conditions", "actions", "enabled", "cooldown_minutes", "max_actions_per_run", "archived_at", "last_run_at", "last_result", "created_by", "created_at", "updated_by", "updated_at") VALUES ('761c9d5c-c1ae-480c-ad66-131a904f4290', 'Escalate overdue tickets', 'Raise an overdue ticket one step and tell the support managers.', 'ticket_overdue', '{"max_level":3}', '[{"type":"escalate_ticket"}]', 1, 240, 25, NULL, NULL, NULL, NULL, '2026-10-23T07:15:17.845Z', NULL, '2026-10-23T07:15:17.845Z');
INSERT INTO "platform_automation_rules" ("id", "name", "description", "trigger", "conditions", "actions", "enabled", "cooldown_minutes", "max_actions_per_run", "archived_at", "last_run_at", "last_result", "created_by", "created_at", "updated_by", "updated_at") VALUES ('1c4daaa3-f0f3-474e-a0ca-fa09fcc396ef', 'Repeated integration failures → technical support', 'Tell technical support when a merchant''s integrations keep failing.', 'integration_failures', '{"hours":24,"min_errors":5}', '[{"type":"notify_staff","action":"edit","module":"integrations","severity":"WARN"},{"type":"notify_account_manager"}]', 1, 1440, 25, NULL, NULL, NULL, NULL, '2026-10-23T07:15:17.845Z', NULL, '2026-10-23T07:15:17.845Z');
