INSERT INTO "platform_automation_rules" ("id", "name", "description", "trigger", "conditions", "actions", "enabled", "cooldown_minutes", "max_actions_per_run", "archived_at", "last_run_at", "last_result", "created_by", "created_at", "updated_by", "updated_at") VALUES ('3f54ac0e-c4b2-4723-adee-bac8e3a5cd19', 'Onboarding reminder', 'Remind merchants who have not finished setting up (in-app).', 'onboarding_incomplete', '{"days":3}', '[{"body":"A few setup steps are still open. Finish them to start taking orders smoothly — or reply to our support team if you need help.","kind":"GENERAL","link":"/admin","type":"notify_merchant","title":"Finish setting up your store","severity":"INFO"},{"type":"notify_account_manager","severity":"INFO"}]', 0, 4320, 25, NULL, NULL, NULL, NULL, '2026-10-23T07:15:17.845Z', NULL, '2026-10-23T07:15:17.845Z');
INSERT INTO "platform_automation_rules" ("id", "name", "description", "trigger", "conditions", "actions", "enabled", "cooldown_minutes", "max_actions_per_run", "archived_at", "last_run_at", "last_result", "created_by", "created_at", "updated_by", "updated_at") VALUES ('0e1d137c-ed96-4256-86cd-d99939fd3c0e', 'Usage limit reached', 'Tell the merchant (in-app) and their account manager when SMS or BD Courier requests are refused.', 'usage_limit', '{"hours":24,"min_refused":1}', '[{"body":"Some SMS or courier history checks could not run because a limit or your credits ran out. Recharge or check your plan under Plan & Billing.","kind":"USAGE","link":"/admin/settings/billing","type":"notify_merchant","title":"A usage limit was reached","severity":"WARN"},{"type":"notify_account_manager","severity":"INFO"}]', 0, 1440, 25, NULL, NULL, NULL, NULL, '2026-10-23T07:15:17.845Z', NULL, '2026-10-23T07:15:17.845Z');
INSERT INTO "platform_automation_rules" ("id", "name", "description", "trigger", "conditions", "actions", "enabled", "cooldown_minutes", "max_actions_per_run", "archived_at", "last_run_at", "last_result", "created_by", "created_at", "updated_by", "updated_at") VALUES ('c5473e29-73c0-4a3c-8ec2-a85b5d7a1a98', 'Credentials expiring', 'Tell the merchant''s account manager and marketing support when a connected Meta account is about to expire.', 'credentials_expiring', '{"days":7}', '[{"type":"notify_staff","action":"edit","module":"integrations","severity":"WARN"},{"type":"notify_account_manager"}]', 1, 1440, 25, NULL, NULL, NULL, NULL, '2026-10-23T07:15:17.845Z', NULL, '2026-10-23T07:15:17.845Z');
INSERT INTO "platform_automation_rules" ("id", "name", "description", "trigger", "conditions", "actions", "enabled", "cooldown_minutes", "max_actions_per_run", "archived_at", "last_run_at", "last_result", "created_by", "created_at", "updated_by", "updated_at") VALUES ('aaa69dda-739d-4124-b6e2-142bca33736e', 'Platform service down → incident', 'Open an incident when the platform SMS, BD Courier or PBX gateway stops working.', 'service_down', '{"minutes":10}', '[{"type":"create_incident","severity":"HIGH"},{"type":"notify_staff","action":"manage","module":"health","severity":"CRITICAL"}]', 1, 60, 25, NULL, NULL, NULL, NULL, '2026-10-23T07:15:17.845Z', NULL, '2026-10-23T07:15:17.845Z');
